// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
app.MapGet("api/shipments", async (IShipmentService svc) =>
    Results.Ok(await svc.GetAllShipmentsAsync()))
    .RequireAuthorization();

app.MapGet("api/shipments/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
{
    var shipment = await svc.GetByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

app.MapPut("api/shipments/{id}/status", async (int id, ShipmentStatus status, IShipmentService svc) =>
{
    var shipment = await svc.UpdateStatusAsync(id, status);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization("DispatcherPolicy");

// Seed database
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
    if (!await roleManager.RoleExistsAsync("Dispatcher"))
        await roleManager.CreateAsync(new IdentityRole("Dispatcher"));
    if (!await roleManager.RoleExistsAsync("Customer"))
        await roleManager.CreateAsync(new IdentityRole("Customer"));

    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "SHP-10001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), RecipientName = "Alice Johnson", Description = "Electronics — 2 boxes" },
            new Shipment { TrackingNumber = "SHP-10002", Origin = "Chicago, IL", Destination = "Houston, TX", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, RecipientName = "Bob Smith", Description = "Furniture — 1 pallet" },
            new Shipment { TrackingNumber = "SHP-10003", Origin = "Miami, FL", Destination = "Seattle, WA", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(7), RecipientName = "Carol Davis", Description = "Medical supplies" },
            new Shipment { TrackingNumber = "SHP-10004", Origin = "Denver, CO", Destination = "Boston, MA", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-3), ActualDelivery = DateTime.UtcNow.AddDays(-4), RecipientName = "Dan Lee", Description = "Auto parts — 3 crates" },
            new Shipment { TrackingNumber = "SHP-10005", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-6), EstimatedDelivery = DateTime.UtcNow.AddDays(1), RecipientName = "Eve Martinez", Description = "Clothing — 5 cartons" }
        );
        db.SaveChanges();
    }
}

app.Run();

