@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="row mb-3 g-2">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search tracking #, destination, or recipient…"
               @bind="searchText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="Refresh">
            🔄 Refresh
        </button>
    </div>
</div>

@if (loading)
{
    <div class="d-flex align-items-center my-4">
        <div class="spinner-border spinner-border-sm me-2" role="status"></div>
        <span>Loading shipments…</span>
    </div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover align-middle">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td>
                            <span class="badge @StatusBadgeClass(s.Status)">@s.Status</span>
                        </td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <div class="d-flex gap-1">
                                    <select class="form-select form-select-sm" style="width:auto" @bind="newStatus">
                                        @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@st">@st</option>
                                        }
                                    </select>
                                    <button class="btn btn-sm btn-success" @onclick="() => SaveStatus(s.Id)" disabled="@saving">
                                        ✓
                                    </button>
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="CancelEdit">
                                        ✕
                                    </button>
                                </div>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">
                                    Update
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filter.</div>
    }
}

@code {
    private List<Shipment> shipments = [];
    private bool loading = true;
    private string searchText = string.Empty;
    private string statusFilter = string.Empty;

    private int? editingId;
    private ShipmentStatus newStatus;
    private bool saving;

    private IEnumerable<Shipment> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrWhiteSpace(statusFilter) &&
            Enum.TryParse<ShipmentStatus>(statusFilter, out var filter) &&
            s.Status != filter)
            return false;

        if (!string.IsNullOrWhiteSpace(searchText))
        {
            var q = searchText.Trim();
            return s.TrackingNumber.Contains(q, StringComparison.OrdinalIgnoreCase)
                || s.Destination.Contains(q, StringComparison.OrdinalIgnoreCase)
                || s.RecipientName.Contains(q, StringComparison.OrdinalIgnoreCase);
        }

        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private async Task Refresh() => await LoadShipments();

    private void StartEdit(Shipment s)
    {
        editingId = s.Id;
        newStatus = s.Status;
    }

    private void CancelEdit() => editingId = null;

    private async Task SaveStatus(int id)
    {
        saving = true;
        var updated = await ShipmentService.UpdateStatusAsync(id, newStatus);
        if (updated is not null)
        {
            var idx = shipments.FindIndex(s => s.Id == id);
            if (idx >= 0) shipments[idx] = updated;
        }
        editingId = null;
        saving = false;
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-secondary"
    };
}

